from __future__ import annotations

import base64
import gzip
import os
from pathlib import Path

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()

V13_B64 = ''
V14_B64 = ''
EXTRA_B64 = ''


def run_embedded(encoded: str, name: str, inherited: dict | None = None) -> tuple[int, dict]:
    source = gzip.decompress(base64.b64decode(encoded)).decode("utf-8")
    ns = {
        "__name__": name,
        "__file__": str(PROJECT / f"_{name}.py"),
    }
    if inherited:
        ns.update(inherited)

    exec(compile(source, ns["__file__"], "exec"), ns)
    result = ns["main"]() if callable(ns.get("main")) else 0
    return int(result or 0), ns


def main() -> int:
    print("=" * 100)
    print("BÀI 13B-6 V1.4 FINAL-2B")
    print("SỬA BỘ CÀI KHÔNG PHỤ THUỘC CHỮ KÝ ROUTE MN-01-GV CŨ")
    print("=" * 100)
    print("")
    print("Nguyên nhân bản FINAL-2A dừng:")
    print(" - report_inputs.py trên máy đã khác chữ ký route của bộ cài V1.3 cũ.")
    print(" - FINAL-2B tìm đúng hàm theo cấu trúc Python, không so khớp nguyên khối văn bản.")
    print("")

    # 1. Bảo đảm V1.3 theo cách thích nghi.
    result13, ns13 = run_embedded(
        V13_B64,
        "embedded_bai_13b_6_v1_3_robust",
    )
    if result13 != 0:
        print("")
        print("FINAL-2B dừng vì bước V1.3 thích nghi chưa đạt.")
        return result13

    # 2. Cài V1.4 FINAL thích nghi.
    result14, ns14 = run_embedded(
        V14_B64,
        "embedded_bai_13b_6_v1_4_robust",
    )
    if result14 != 0:
        print("")
        print("FINAL-2B dừng vì bước V1.4 chưa đạt.")
        return result14

    # 3. Tách Danh mục trường + TK trường theo 3 cấp.
    extra_source = gzip.decompress(base64.b64decode(EXTRA_B64)).decode("utf-8")
    extra_ns = {
        "__name__": "embedded_bai_13b_6_v1_4_final2_extra",
        "__file__": str(PROJECT / "_embedded_bai_13b_6_v1_4_final2_extra.py"),
        "PROJECT": ns14["PROJECT"],
        "APP": ns14["APP"],
    }
    exec(compile(extra_source, extra_ns["__file__"], "exec"), extra_ns)

    result_extra = int(extra_ns["run_final2"](ns14))
    if result_extra != 0:
        return result_extra

    print("")
    print("=" * 100)
    print("CAI DAT BAI 13B-6 V1.4 FINAL-2B THANH CONG")
    print("=" * 100)
    print(" - Đã xử lý route MN-01-GV hiện tại theo AST.")
    print(" - Đã hoàn thiện V1.4.")
    print(" - Đã tách Danh mục trường MN / Tiểu học / THCS.")
    print(" - Đã tách TK trường MN / Tiểu học / THCS.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
